#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    errno = 0;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno != 0) {
        puts("BAD_INPUT");
        return 0;
    }
    errno = 0;
    long k = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0' || errno != 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000L || k > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long survivor = 0;
    for (long i = 2; i <= n; ++i) {
        survivor = (survivor + k) % i;
    }
    printf("%ld\n", survivor + 1);
    return 0;
}
